/*
 * A153040  Numbers n>3 such that 2*n-5 is not a prime.
 * https://oeis.org/A153040
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = the (n)-th integer > 3 such that 2*a(n)-5 is composite
 * Range:     u8 n <= 156, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   is_prime_small
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The sequence is generated by testing each integer > 3 in turn and
   selecting those for which 2*n-5 is not prime.  The result is cached
   so that subsequent calls to a() are fast, regardless of the order of
   the indices. */

#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>
#include "../utils/is_prime_small.h"   /* provides bool is_prime_small(uint64_t) */

static seq_t *cache = NULL;
static idx_t  cache_size = 0;   /* number of terms stored */
static idx_t  cache_cap   = 0;   /* allocated capacity of cache */
static idx_t  last_checked = 3; /* last integer candidate examined */

/* Ensure the cache has enough room to add another element. */
static void grow_cache(void)
{
    size_t new_cap = cache_cap ? cache_cap * 2 : 8;
    seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
    if (tmp == NULL) {
        /* In a sequence generation context we can abort on allocation
           failure; no output is required. */
        exit(EXIT_FAILURE);
    }
    cache = tmp;
    cache_cap = new_cap;
}

/* Return the n-th term of OEIS A153040 (n >= 1). */
seq_t a(idx_t n)
{
    if (n == 0) return 0;   /* undefined but safe guard */

    /* Grow the cache until it contains at least n values. */
    while (cache_size < n) {
        idx_t cand = ++last_checked;            /* next integer to test */

        if (cand > 3) {
            uint64_t m = (uint64_t)2 * cand - 5; /* compute 2*cand-5 */
            bool prime = is_prime_small(m);
            if (!prime) {                      /* composite or not prime */
                if (cache_size == cache_cap)
                    grow_cache();
                cache[cache_size++] = (seq_t)cand;
            }
        }
    }

    return cache[n - 1];
}
